      <div class="sub">печенек · <span id="cps">0</span> в секунду</div>
    </div>
    <div class="panel cookie-zone">
      <div class="cookie" id="cookie" title="Кликай!">
        <div class="chip c1"></div><div class="chip c2"></div>
        <div class="chip c3"></div><div class="chip c4"></div>
        <div class="chip c5"></div><div class="chip c6"></div>
      </div>
    </div>
    <div class="panel stats">
      <div><b id="clicks">0</b>кликов</div>
      <div><b id="total">0</b>всего печенек</div>
      <div><b id="clickPow">1</b>за клик</div>
    </div>
    <div class="panel">
      <div class="toolbar">
        <button class="btn" id="saveBtn">💾 Сохранить</button>
        <button class="btn danger" id="resetBtn">🗑 Сбросить</button>
      </div>
    </div>
  </div>
  <div class="right">
    <div class="panel">
      <div class="shop-title">
        <h2>Улучшения</h2><span id="upgHint"></span>
      </div>
      <div class="upgrades-row" id="upgrades"></div>
    </div>
    <div class="panel">
      <div class="shop-title">
        <h2>Постройки</h2><span id="cpsTotal">0 печенек/с</span>
      </div>
      <div id="buildings"></div>
    </div>
  </div>
</div>
<div class="golden" id="golden" title="Золотая печенька!"></div>
<div class="toast" id="toast"></div>

<script>
"use strict";

const SAVE_KEY = "clicker-save-v1";

const BUILDINGS = [
  { id: "cursor",   name: "Курсор",   desc: "Кликает за тебя.",        baseCost: 15,     cps: 0.1,   icon: "🖱️" },
  { id: "grandma",  name: "Бабушка",  desc: "Печёт печеньки.",         baseCost: 100,    cps: 1,     icon: "👵" },
  { id: "farm",     name: "Ферма",    desc: "Растит сахарный тростник.", baseCost: 1100, cps: 8,     icon: "🌾" },
  { id: "mine",     name: "Шахта",    desc: "Добывает шоколад.",       baseCost: 12000,  cps: 47,    icon: "⛏️" },
  { id: "factory",  name: "Фабрика",  desc: "Конвейер печенек.",       baseCost: 130000, cps: 260,   icon: "🏭" },
  { id: "bank",     name: "Банк",     desc: "Проценты на печеньки.",   baseCost: 1.4e6,  cps: 1400,  icon: "🏦" },
  { id: "temple",   name: "Храм",     desc: "Молитвы о печеньках.",    baseCost: 2e7,    cps: 7800,  icon: "⛩️" },
  { id: "portal",   name: "Портал",   desc: "Печеньки из другого измерения.", baseCost: 3.3e8, cps: 44000, icon: "🌀" },
];

const UPGRADES = [
  { id: "u1", name: "Усиленный клик ×2",  desc: "Клик приносит вдвое больше.", cost: 100,    need: 500,    type: "click", mult: 2 },
  { id: "u2", name: "Мегаклик ×2",        desc: "Клик приносит ещё вдвое больше.", cost: 1e4, need: 5e4,   type: "click", mult: 2 },
  { id: "u3", name: "Гигаклик ×2",        desc: "Просто безумный клик.",        cost: 1e6,    need: 5e6,    type: "click", mult: 2 },
  { id: "u4", name: "Тераклик ×2",        desc: "Клик = стихийное бедствие.",    cost: 1e8,    need: 5e8,    type: "click", mult: 2 },
  { id: "u5", name: "Конвейер ×2",        desc: "Все постройки работают вдвое быстрее.", cost: 500, need: 2e3,  type: "cps", mult: 2 },
  { id: "u6", name: "Роботы ×2",          desc: "Автоматизация печенек.",       cost: 5e4,    need: 2e5,    type: "cps", mult: 2 },
  { id: "u7", name: "ИИ-пекарня ×2",      desc: "Нейросети выпекают лучше.",     cost: 5e6,    need: 2e7,    type: "cps", mult: 2 },
  { id: "u8", name: "Квантовая печь ×2",  desc: "Печеньки из всех вселенных.",   cost: 5e8,    need: 2e9,    type: "cps", mult: 2 },
];

const state = {
  cookies: 0,
  total: 0,
  clicks: 0,
  clickPower: 1,
  buildings: Object.fromEntries(BUILDINGS.map(b => [b.id, 0])),
  upgrades: Object.fromEntries(UPGRADES.map(u => [u.id, false])),
};

const $ = id => document.getElementById(id);

function fmt(n) {
  if (n < 0) return "-" + fmt(-n);
  if (n < 1000) return n < 10 && n % 1 !== 0 ? n.toFixed(1) : Math.floor(n).toString();
  const units = ["K", "M", "B", "T", "Qa", "Qi", "Sx", "Sp", "Oc", "No", "Dc"];
  let u = -1;
  while (n >= 1000 && u < units.length - 1) { n /= 1000; u++; }
  const digits = n >= 100 ? 0 : n >= 10 ? 1 : 2;
  return n.toFixed(digits) + units[u];
}

function costOf(b) {
  return Math.ceil(b.baseCost * Math.pow(1.15, state.buildings[b.id]));
}

function buildingCps(b) {
  return b.cps * state.buildings[b.id] * cpsMult();
}

function cpsMult() {
  let m = 1;
  for (const u of UPGRADES) if (u.type === "cps" && state.upgrades[u.id]) m *= u.mult;
  return m;
}

function totalCps() {
  return BUILDINGS.reduce((s, b) => s + buildingCps(b), 0);
}

function clickPower() {
  let p = state.clickPower;
  for (const u of UPGRADES) if (u.type === "click" && state.upgrades[u.id]) p *= u.mult;
  return p;
}

function toast(msg) {
  const t = $("toast");
  t.textContent = msg;
  t.classList.add("show");
  clearTimeout(t._h);
  t._h = setTimeout(() => t.classList.remove("show"), 2000);
}

function save() {
  try {
    localStorage.setItem(SAVE_KEY, JSON.stringify(state));
  } catch (e) { /* приватный режим — просто не сохраняем */ }
}

function load() {
  try {
    const raw = localStorage.getItem(SAVE_KEY);
    if (!raw) return false;
    const s = JSON.parse(raw);
    for (const k of Object.keys(state)) if (k in s) state[k] = s[k];
    for (const b of BUILDINGS) if (!(b.id in state.buildings)) state.buildings[b.id] = 0;
    return true;
  } catch (e) { return false; }
}

/* ---------- клик по печеньке ---------- */

$("cookie").addEventListener("click", e => {
  const gain = clickPower();
  state.cookies += gain;
  state.total += gain;
  state.clicks++;
  spawnFloat(e.clientX, e.clientY, "+" + fmt(gain));
});

function spawnFloat(x, y, text) {
  const el = document.createElement("div");
  el.className = "float-num";
  el.textContent = text;
  el.style.left = (x - 20 + (Math.random() * 40 - 20)) + "px";
  el.style.top = (y - 20) + "px";
  document.body.appendChild(el);
  setTimeout(() => el.remove(), 1000);
}

/* ---------- постройки и улучшения ---------- */

const buildingsEl = $("buildings");
for (const b of BUILDINGS) {
  const row = document.createElement("div");
  row.className = "building";
  row.id = "b-" + b.id;
  row.innerHTML =
    '<div class="icon">' + b.icon + "</div>" +
    '<div class="info"><div class="name">' + b.name + "</div>" +
    '<div class="desc">' + b.desc + " · " + fmt(b.cps) + " п/с</div></div>" +
    '<div class="price">' + fmt(b.baseCost) + "</div>" +
    '<div class="owned">0</div>';
  row.addEventListener("click", () => buy(b));
  buildingsEl.appendChild(row);
}

function buy(b) {
  const cost = costOf(b);
  if (state.cookies < cost) return;
  state.cookies -= cost;
  state.buildings[b.id]++;
  save();
}

const upgradesEl = $("upgrades");
for (const u of UPGRADES) {
  const el = document.createElement("div");
  el.className = "upgrade hidden";
  el.id = "u-" + u.id;
  el.innerHTML = '<div class="u-name">' + u.name + '</div><div class="u-desc">' + u.desc +
    '</div><div class="u-cost">' + fmt(u.cost) + " 🍪</div>";
  el.addEventListener("click", () => {
    if (state.cookies < u.cost || state.upgrades[u.id]) return;
    state.cookies -= u.cost;
    state.upgrades[u.id] = true;
    toast("Куплено: " + u.name + "!");
    save();
  });
  upgradesEl.appendChild(el);
}

/* ---------- золотая печенька ---------- */

const golden = $("golden");
let goldenTimer = null;

function scheduleGolden() {
  clearTimeout(goldenTimer);
  goldenTimer = setTimeout(showGolden, 30000 + Math.random() * 45000);
}

function showGolden() {
  if (state.total < 100) { scheduleGolden(); return; }
  golden.style.display = "block";
  golden.style.left = (10 + Math.random() * (window.innerWidth - 130)) + "px";
  golden.style.top = (10 + Math.random() * (window.innerHeight - 130)) + "px";
  golden._hide = setTimeout(hideGolden, 15000);
}

function hideGolden() {
  golden.style.display = "none";
  clearTimeout(golden._hide);
  scheduleGolden();
}

golden.addEventListener("click", e => {
  e.stopPropagation();
  const reward = Math.max(100, Math.floor((state.total * 0.15 + 100) * (0.7 + Math.random() * 0.6)));
  state.cookies += reward;
  state.total += reward;
  spawnFloat(e.clientX, e.clientY, "+" + fmt(reward) + " ✨");
  toast("Золотая печенька! +" + fmt(reward));
  hideGolden();
  save();
});

/* ---------- рендер ---------- */

function render() {
  $("cookies").textContent = fmt(state.cookies);
  $("cps").textContent = fmt(totalCps());
  $("clicks").textContent = fmt(state.clicks);
  $("total").textContent = fmt(state.total);
  $("clickPow").textContent = fmt(clickPower());
  $("cpsTotal").textContent = fmt(totalCps()) + " печенек/с";

  for (const b of BUILDINGS) {
    const row = $("b-" + b.id);
    const cost = costOf(b);
    row.querySelector(".price").textContent = fmt(cost);
    row.querySelector(".owned").textContent = state.buildings[b.id];
    row.classList.toggle("afford", state.cookies >= cost);
  }

  let shown = 0;
  for (const u of UPGRADES) {
    const el = $("u-" + u.id);
    const unlocked = state.upgrades[u.id] || state.total >= u.need;
    el.classList.toggle("hidden", !unlocked);
    el.style.opacity = state.upgrades[u.id] ? 0.55 : 1;
    el.style.cursor = state.upgrades[u.id] ? "default" : "pointer";
    if (unlocked && !state.upgrades[u.id]) shown++;
  }
  $("upgHint").textContent = shown ? "доступно: " + shown : "";
}

/* ---------- управление ---------- */

$("saveBtn").addEventListener("click", () => { save(); toast("Сохранено!"); });
$("resetBtn").addEventListener("click", () => {
  if (!confirm("Точно сбросить весь прогресс?")) return;
  for (const k of Object.keys(state)) {
    if (typeof state[k] === "number") state[k] = 0;
    else if (typeof state[k] === "object") {
      for (const id of Object.keys(state[k])) state[k][id] = typeof state[k][id] === "number" ? 0 : false;
    }
  }
  state.clickPower = 1;
  localStorage.removeItem(SAVE_KEY);
  toast("Прогресс сброшен");
});

window.addEventListener("beforeunload", save);
window.addEventListener("resize", () => {
  if (golden.style.display === "block") {
    golden.style.left = Math.min(parseFloat(golden.style.left), window.innerWidth - 130) + "px";
    golden.style.top = Math.min(parseFloat(golden.style.top), window.innerHeight - 130) + "px";
  }
});

/* ---------- запуск ---------- */

if (load()) toast("Прогресс загружен!");

setInterval(() => {
  const gain = totalCps() / 10;
  if (gain > 0) { state.cookies += gain; state.total += gain; }
}, 100);

setInterval(render, 100);
setInterval(save, 15000);
scheduleGolden();
render();
</script>
</body>
</html>
"}

